// Recibir datos del formulario de tu app Noxertez
// Tu app Flask manda un POST con estos campos:
// { cliente, telefono, items: [{referencia, nombre, cantidad, precio}], canal, notas }

const body = $input.first().json;

// Validar que vienen los campos mínimos
if (!body.items || body.items.length === 0) {
  throw new Error('El pedido no tiene artículos');
}

const numeroPedido = 'PED-' + Date.now();
let total = 0;

const items = body.items.map(item => {
  const subtotal = (item.precio || 0) * (item.cantidad || 1);
  total += subtotal;
  return {
    referencia: item.referencia || 'SIN-REF',
    nombre: item.nombre || item.referencia,
    cantidad: item.cantidad || 1,
    precio_unit: item.precio || 0,
    subtotal: subtotal
  };
});

return [{ json: {
  numero_pedido: numeroPedido,
  telefono: body.telefono || '',
  nombre_cliente: body.cliente || 'Cliente sin nombre',
  items_json: JSON.stringify(items),
  total: total,
  estado: 'pendiente',
  fecha_pedido: new Date().toISOString(),
  canal: body.canal || 'manual',
  notas: body.notas || ''
}}];

